trait Container {
    type Item;
    fn get(&self, i: usize) -> Option<&Self::Item>;
}

struct Bag { values: Vec<String> }

impl Container for Bag {
    type Item = String;
    fn get(&self, index: usize) -> Option<&String> {
        self.values.get(index)
    }
}

